const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-70.647985, -34.752733]);
  const date2023 = ee.Date('2023-12-18');
  const historicalYears = [2017, 2018, 2019, 2020, 2021, 2022];

  // 2. Data Acquisition for 2023
  let col2023 = ee.ImageCollection('MODIS/006/MOD10A1')
    .filterBounds(point)
    .filterDate(date2023, date2023.advance(1, 'day'))
    .select('NDSI_Snow_Cover');

  let size2023 = col2023.size().getInfo();
  console.log(`2023-12-18 Images: ${size2023}`);

  if (size2023 === 0) {
    // Try Terra+Aqua combined
    col2023 = ee.ImageCollection('MODIS/006/MYD10A1')
      .filterBounds(point)
      .filterDate(date2023, date2023.advance(1, 'day'))
      .select('NDSI_Snow_Cover');
    size2023 = col2023.size().getInfo();
    console.log(`2023-12-18 Aqua Images: ${size2023}`);
  }

  if (size2023 === 0) {
    console.log("No data for 2023-12-18.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Process 2023 data
  const img2023 = col2023.first();
  const snowCover2023Raw = img2023.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: point,
    scale: 500,
    maxPixels: 1e9
  }).get('NDSI_Snow_Cover');

  const snowCover2023 = snowCover2023Raw.getInfo();

  if (snowCover2023 === null || snowCover2023 === undefined) {
    console.log("2023 data invalid (likely masked).");
    console.log("<answer>C2</answer>");
    return;
  }

  console.log(`2023-12-18 Snow Cover: ${snowCover2023.toFixed(2)}%`);

  // 4. Data Acquisition for Historical Years (2017-2022)
  const historicalValues = [];

  for (const year of historicalYears) {
    const dateStr = `${year}-12-18`;
    const startDate = ee.Date(dateStr);
    const endDate = startDate.advance(1, 'day');

    let colYear = ee.ImageCollection('MODIS/006/MOD10A1')
      .filterBounds(point)
      .filterDate(startDate, endDate)
      .select('NDSI_Snow_Cover');

    const sizeYear = colYear.size().getInfo();

    if (sizeYear === 0) {
      colYear = ee.ImageCollection('MODIS/006/MYD10A1')
        .filterBounds(point)
        .filterDate(startDate, endDate)
        .select('NDSI_Snow_Cover');
    }

    const sizeYearFinal = colYear.size().getInfo();

    if (sizeYearFinal > 0) {
      const imgYear = colYear.first();
      const snowCoverYear = imgYear.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: point,
        scale: 500,
        maxPixels: 1e9
      }).get('NDSI_Snow_Cover').getInfo();

      if (snowCoverYear !== null && snowCoverYear !== undefined) {
        historicalValues.push(snowCoverYear);
        console.log(`${year}-12-18: ${snowCoverYear.toFixed(2)}%`);
      } else {
        console.log(`${year}-12-18: No valid data`);
      }
    } else {
      console.log(`${year}-12-18: No images`);
    }
  }

  // 5. Validation & Final Answer
  if (historicalValues.length === 0) {
    console.log("No valid historical data found.");
    console.log("<answer>C1</answer>");
    return;
  }

  const avgHistorical = historicalValues.reduce((a, b) => a + b, 0) / historicalValues.length;
  console.log(`Historical Average (${historicalValues.length} years): ${avgHistorical.toFixed(2)}%`);

  if (snowCover2023 > avgHistorical) {
    console.log(`2023 (${snowCover2023.toFixed(2)}%) > Historical Avg (${avgHistorical.toFixed(2)}%)`);
    console.log("<answer>A</answer>");
  } else {
    console.log(`2023 (${snowCover2023.toFixed(2)}%) <= Historical Avg (${avgHistorical.toFixed(2)}%)`);
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
